changeSet.sql:

if not exists (select 1 from [sys].[key_constraints] where name = 'PK_MetricAsset')
begin
	ALTER TABLE [metrics].[Asset] ADD CONSTRAINT [PK_MetricAsset] PRIMARY KEY NONCLUSTERED ( [Uid] ASC )
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAsset_MetricAllocation')
begin
	ALTER TABLE [metrics].[Asset] WITH CHECK ADD  CONSTRAINT [FK_MetricAsset_MetricAllocation] FOREIGN KEY([AllocationUid]) REFERENCES [metrics].[Allocation] ([Uid]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[Asset] CHECK CONSTRAINT [FK_MetricAsset_MetricAllocation];	
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAsset_Parent')
begin
	ALTER TABLE [metrics].[Asset] WITH CHECK ADD  CONSTRAINT [FK_MetricAsset_Parent] FOREIGN KEY([ParentUid]) REFERENCES [metrics].[Asset] ([Uid]);
	ALTER TABLE [metrics].[Asset] CHECK CONSTRAINT [FK_MetricAsset_Parent];
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricsAsset_uid')
begin
	ALTER TABLE [metrics].[Asset] ADD CONSTRAINT [DF_MetricsAsset_uid]  DEFAULT (newid()) FOR [Uid]
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAsset_IsGroup')
begin
	ALTER TABLE [metrics].[Asset] ADD CONSTRAINT [DF_MetricAsset_IsGroup]  DEFAULT ((1)) FOR [IsGroup]
end

if not exists (select * from [sys].[default_constraints] where [type] = 'D' and name = 'DF_MetricAsset_State')
begin
	ALTER TABLE [metrics].[Asset] ADD CONSTRAINT [DF_MetricAsset_State]  DEFAULT ((1)) FOR [State]
end
